svg.script:
(function () {
  // Loi normale μ = 14 mm, σ = 0,1 mm. Échelle : 500 px par mm, μ en x = 240, axe en y = 250.
  var MU = 14, SG = 0.1, PX = 500, X0 = 240, AXE = 250, H = 470, K_QUESTION = 2;
  var $ = function (id) { return document.getElementById(id); };
  var svg = document.documentElement;
  function phi(z) { return Math.exp(-z * z / 2) / Math.sqrt(2 * Math.PI); }
  function erf(x) {   // Abramowitz et Stegun 7.1.26, erreur < 2e-7
    var t = 1 / (1 + 0.3275911 * x);
    return 1 - (((((1.061405429 * t - 1.453152027) * t) + 1.421413741) * t - 0.284496736) * t + 0.254829592) * t * Math.exp(-x * x);
  }
  function proba(k) { return erf(k / Math.SQRT2); }   // P(μ − kσ ≤ X ≤ μ + kσ)
  function fr(v, d) { return v.toFixed(d).replace(".", ","); }
  var k = K_QUESTION;

  function dessiner() {
    var xg = X0 - k * SG * PX, xd = X0 + k * SG * PX, pts = [];
    for (var i = 0; i <= 80; i++) {
      var z = -k + 2 * k * i / 80;
      pts.push((X0 + z * SG * PX).toFixed(1) + " " + (AXE - phi(z) * H).toFixed(1));
    }
    $("aire").setAttribute("d", "M" + xg.toFixed(1) + " " + AXE + " L" + pts.join(" L") + " L" + xd.toFixed(1) + " " + AXE + " Z");
    [["g", xg], ["d", xd]].forEach(function (c) {
      $("z" + c[0]).setAttribute("x", c[1] - 20);
      $("l" + c[0]).setAttribute("x1", c[1]); $("l" + c[0]).setAttribute("x2", c[1]);
      $("l" + c[0]).setAttribute("y2", AXE - phi(k) * H);
      $("c" + c[0]).setAttribute("cx", c[1]);
    });
    $("kk").textContent = "μ ± " + fr(k, 2) + " σ";
    $("resultat").textContent = "P(" + fr(MU - k * SG, 2) + " ≤ X ≤ " + fr(MU + k * SG, 2) + ") ≈ " + fr(proba(k), 3);
  }

  function finirAnimations() {
    Array.prototype.forEach.call(document.querySelectorAll(".anim, .trace"), function (el) { el.classList.remove("anim"); el.classList.remove("trace"); });
  }
  function versSVG(e) {
    var p = svg.createSVGPoint(); p.x = e.clientX; p.y = e.clientY;
    return p.matrixTransform(svg.getScreenCTM().inverse());
  }
  var actif = null;
  ["pg", "pd"].forEach(function (id) {
    var g = $(id);
    g.addEventListener("pointerdown", function (e) {
      actif = id; finirAnimations(); $("aide").setAttribute("visibility", "hidden");
      g.setPointerCapture(e.pointerId); e.preventDefault();
    });
    g.addEventListener("pointermove", function (e) {
      if (actif !== id) return;
      k = Math.max(0.1, Math.min(3.9, Math.abs(versSVG(e).x - X0) / (SG * PX)));
      dessiner();
    });
    function lacher() { if (actif) verifierDefi(); actif = null; }
    g.addEventListener("pointerup", lacher);
    g.addEventListener("pointercancel", lacher);
  });

  $("rejouer").addEventListener("click", function () {
    k = K_QUESTION; defi = -1; $("defi").setAttribute("visibility", "hidden"); dessiner();
  });

  // Défi : régler l'intervalle pour obtenir une probabilité donnée (tolérance large pour le doigt)
  var DEFIS = [
    { texte: "une probabilité d'environ 0,683", k: 1 },
    { texte: "une probabilité de 0,95 (intervalle de confiance)", k: 1.96 },
    { texte: "une probabilité d'environ 0,997", k: 3 }
  ];
  var defi = -1;
  function afficherDefi() {
    $("defi").setAttribute("visibility", "visible");
    $("defifond").setAttribute("stroke", "#d9b26f");
    $("defi1").textContent = "🎯 Défi " + (defi + 1) + "/" + DEFIS.length + " : règle les bornes pour obtenir";
    $("defi2").textContent = DEFIS[defi].texte;
  }
  function verifierDefi() {
    if (defi < 0) return;
    if (Math.abs(k - DEFIS[defi].k) > 0.08) return;
    k = DEFIS[defi].k; dessiner();                       // on aligne sur la valeur exacte
    $("defifond").setAttribute("stroke", "#5fd08a");
    $("defi1").textContent = "✓ Bravo ! C'est μ ± " + fr(k, 2).replace(",00", "") + " σ";
    var fini = defi === DEFIS.length - 1;
    $("defi2").textContent = fini ? "Tous les défis sont réussis 🎉" : "Défi suivant dans un instant…";
    var suivant = defi + 1; defi = fini ? -1 : -2;
    if (!fini) setTimeout(function () { defi = suivant; afficherDefi(); }, 1600);
  }
  $("bdefi").addEventListener("click", function () {
    finirAnimations(); $("aide").setAttribute("visibility", "visible"); defi = 0; afficherDefi();
  });

  // Réponse fausse de l'élève (numéros = position dans q.choix de questions-U41.js)
  var ERREURS = {
    0: { g: 13.9, d: 14.1, val: "0,68 (de 13,9 à 14,1)", pourquoi: "0,68, c'est μ ± 1σ. Ici 0,2 mm = 2 écarts types." },
    2: { g: 13.7, d: 14.3, val: "0,997 (de 13,7 à 14,3)", pourquoi: "0,997, c'est μ ± 3σ : intervalle trop large." },
    3: { g: 13.6, d: 14, val: "0,5 (tout ce qui est sous 14)", pourquoi: "0,5, c'est P(X ≤ 14) : la moitié de la courbe." }
  };
  var m = /faux=(\d)/.exec(location.hash);
  var err = m && ERREURS[m[1]];
  if (err) {
    svg.setAttribute("viewBox", "0 0 480 450");
    var xg = X0 + (err.g - MU) * PX, xd = X0 + (err.d - MU) * PX;
    $("errg").setAttribute("x1", xg); $("errg").setAttribute("x2", xg);
    $("errd").setAttribute("x1", xd); $("errd").setAttribute("x2", xd);
    if (err.g < 13.65) $("errg").setAttribute("visibility", "hidden");
    $("errtag").setAttribute("x", err.g < 13.65 ? xd : xg);
    $("errval").textContent = err.val;
    $("errpourquoi").textContent = "→ " + err.pourquoi;
    $("erreur").setAttribute("visibility", "visible");
    $("aide").setAttribute("visibility", "hidden");
  }
  dessiner();
})();
